function isAdmin(){return window.__ubruUser?.role==='admin'}
function save(){}
function room(id){return rooms.find(r=>r.id===Number(id))||rooms[0]}
function navIcon(icon){return icon.startsWith('fa-')?icon:`bi bi-${icon}`}
function toggleSidebar(){const app=document.querySelector('.app');if(!app)return;const open=!app.classList.contains('nav-open');app.classList.toggle('nav-open',open);document.body.classList.toggle('sidebar-open',open);const button=app.querySelector('.sidebar-toggle');if(button)button.setAttribute('aria-expanded',String(open));if(open)app.querySelector('.side-link')?.focus()}
function closeSidebar(restoreFocus=true){const app=document.querySelector('.app');if(!app)return;const wasOpen=app.classList.contains('nav-open');app.classList.remove('nav-open');document.body.classList.remove('sidebar-open');const button=app.querySelector('.sidebar-toggle');if(button){button.setAttribute('aria-expanded','false');if(wasOpen&&restoreFocus)button.focus()}}
window.addEventListener('keydown',event=>{if(event.key==='Escape')closeSidebar()});
function go(page){closeSidebar(false);const next=String(page||'home');if(apiReady&&!isAdmin()&&next.startsWith('admin')){state.page='home';location.hash='home';return}state.page=next;location.hash=next;render()}
window.addEventListener('hashchange',()=>{closeSidebar(false);const next=location.hash.slice(1)||'home';if(apiReady&&!isAdmin()&&next.startsWith('admin')){state.page='home';location.hash='home';return}state.page=next;render()});
function shell(content){if(isAdmin())return adminShell(content);const profileName=currentUser?.name||'ผู้ใช้ทดสอบ',profileMeta=currentUser?.department||'FOR TEST / EDUCATION ONLY';return `<div class="app"><aside id="site-sidebar" class="sidebar" aria-label="Main menu"><div class="brand"><div class="brand-icon">น</div><div><strong>ระบบจองห้อง</strong><small>มหาวิทยาลัยราชภัฏอุบลราชธานี</small></div></div><nav class="side-nav">${nav.map(n=>`<a class="side-link ${state.page===n[0]||state.page==='detail'&&n[0]==='search'?'active':''}" href="#${n[0]}" onclick="closeSidebar(false)"><i class="${navIcon(n[2])}"></i><span>${n[1]}</span></a>`).join('')}</nav><div class="profile"><i class="bi bi-person-fill"></i><div class="profile-info"><strong>${esc(profileName)}</strong><small>${esc(profileMeta)}</small></div><button class="logout-btn" onclick="logout()" title="ออกจากระบบ"><i class="bi bi-box-arrow-right"></i></button></div></aside><button class="sidebar-overlay" type="button" aria-label="Close menu" onclick="closeSidebar()"></button><main class="main">${content}</main></div>`}
function adminShell(content){return `<div class="app admin-app"><aside id="site-sidebar" class="sidebar admin-sidebar" aria-label="Admin menu"><div class="brand"><div class="brand-icon admin-mark">อ</div><div><strong>ระบบผู้ดูแลระบบ</strong><small>สำนักงานคณะเกษตรศาสตร์</small></div></div><nav class="side-nav">${adminNav.map(n=>`<a class="side-link ${state.page===n[0]?'active':''}" href="#${n[0]}" onclick="closeSidebar(false)"><i class="bi bi-${n[2]}"></i><span>${n[1]}</span></a>`).join('')}</nav><div class="profile"><i class="bi bi-person-fill"></i><div class="profile-info"><strong>แอดมิน</strong><small>ผู้ดูแลระบบ</small></div><button class="logout-btn" onclick="logout()" title="ออกจากระบบ"><i class="bi bi-box-arrow-right"></i></button></div></aside><button class="sidebar-overlay" type="button" aria-label="Close menu" onclick="closeSidebar()"></button><main class="main">${content}</main></div>`}
function head(title,desc){let isDark=document.body.classList.contains('dark-mode'),unread=notifications.filter(n=>!n.read_at).length,adminBadge=unread?`<span class="notify-badge">${unread>99?'99+':unread}</span>`:'';return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions"><button class="sidebar-toggle" type="button" aria-controls="site-sidebar" aria-expanded="false" aria-label="Open menu" title="Open menu" onclick="toggleSidebar()"><i class="bi bi-list"></i></button><button class="theme-toggle" onclick="toggleTheme()" title="สลับโหมดสี"><i class="bi bi-${isDark?'sun':'moon-stars'}"></i></button><button class="notify" onclick="go('notifications')"><i class="bi bi-bell"></i>${adminBadge}</button></div></div>`}
function safeImageUrl(value){try{let url=new URL(String(value||''),location.href),sameOrigin=url.origin===location.origin;return sameOrigin||url.protocol==='https:'?esc(url.href):''}catch{return''}}
function roomCard(r){return `<article class="room-card"><img class="room-img" src="${safeImageUrl(r.img)}" alt="${esc(r.name)}"><div class="room-body"><span class="room-tag">${esc(r.type)}</span><span class="room-approval ${r.approvalRequired?'special':'general'}">${r.approvalRequired?'ห้องพิเศษ • รอแอดมินอนุมัติ':'ห้องทั่วไป • อนุมัติอัตโนมัติ'}</span><h3>${esc(r.name)}</h3><div class="muted">${esc(r.building)}</div><div class="room-meta"><span><i class="bi bi-people"></i> ความจุ ${Number(r.capacity)||0} คน</span><span><i class="bi bi-projector"></i><i class="bi bi-wifi"></i></span></div><button class="btn-green" onclick="state.selectedRoom=${Number(r.id)||0};go('detail')">ดูรายละเอียด</button></div></article>`}
function home(){return head('ยินดีต้อนรับสู่ระบบจองห้อง','ค้นหาและสำรองห้องเรียน ห้องประชุม หรือห้องปฏิบัติการภายในมหาวิทยาลัยได้อย่างรวดเร็ว')+`<div class="searchbar"><button class="btn-green" onclick="go('search')"><i class="bi bi-plus-lg"></i> จองห้องเรียน/ห้องประชุม</button><div class="search-input"><i class="bi bi-search"></i><input class="form-control" placeholder="ค้นหาชื่อห้องหรืออาคาร..." oninput="state.search=this.value;render()"></div><button class="btn-outline"><i class="bi bi-calendar3"></i> ระบุวันที่จอง</button><button class="btn-outline"><i class="bi bi-clock"></i> ระบุเวลา</button><button class="btn-green" onclick="go('search')">ค้นหา</button></div><h2 class="section-title">ประเภทห้องที่มี</h2><div class="room-grid">${rooms.map(roomCard).join('')}</div><div class="panel mt-4"><div class="d-flex justify-content-between"><h2 class="section-title">ประกาศจากผู้ดูแลระบบ</h2><a href="#rules" class="text-success small">ดูทั้งหมด</a></div><div class="notice-row"><span class="status pending">เปิดรับปรุง</span> ขอให้บริการห้องประชุม 3 อาคาร 51 ในวันเสาร์ที่ 15 เนื่องจากปรับปรุงระบบเครือข่าย</div><div class="notice-row mt-2"><span class="status approved">ข่าวประชาสัมพันธ์</span> เริ่มเปิดให้จองห้องประชุมล่วงหน้าได้ตั้งแต่วันนี้</div></div>`}
