function adminDashboard(){let cards=[['house','จำนวนห้องให้บริการทั้งหมด','59 ห้อง'],['card-checklist','อัตราการจองวันนี้','24 รายการ'],['check-lg','รอการอนุมัติวันนี้','5 คำขอ'],['people','ผู้ใช้งานทั้งหมด','156 คน']];return head('ภาพรวมผู้ดูแลระบบ','ยินดีต้อนรับกลับ แอดมิน • รายงานสถิติภาพรวม คำขอจองห้องเรียน และประกาศอัปเดต')+`<div class="admin-stats">${cards.map((c,i)=>`<div class="stat-card"><div class="stat-icon"><i class="bi bi-${c[0]}"></i></div><div><span class="muted">${c[1]}</span><strong>${c[2]}</strong></div></div>`).join('')}</div><div class="admin-grid"><div class="panel"><h2 class="section-title">รายการคำขออนุมัติใช้งานล่าสุด</h2>${['กิตติศักดิ์ สีดี','อาจารย์ พรชนก','สุดเขต สุขใจ'].map((x,i)=>`<div class="approval-item"><div><strong>${x}</strong><small>คณะเกษตรศาสตร์</small></div><div><span>ห้องประชุม ${i+1}</span><small>${12+i} ต.ค. (09:00 - 12:00 น.)</small></div><div class="approval-actions"><button class="btn-approve" onclick="toast('อนุมัติรายการแล้ว')">อนุมัติ</button><button class="btn-reject" onclick="toast('ปฏิเสธรายการแล้ว')">ปฏิเสธ</button></div></div>`).join('')}</div><div><div class="panel mb-3"><h2 class="section-title">การเข้าใช้งานวันนี้ (ตามประเภท)</h2>${[['ห้องประชุม','12/15 ห้อง','80%'],['ห้องปฏิบัติการ','5/8 ห้อง','62%'],['ห้องเรียน','28/30 ห้อง','93%'],['ห้องอบรม','3/6 ห้อง','50%']].map(x=>`<div class="usage-row"><div><b>${x[0]}</b><span>${x[1]}</span></div><div class="usage-bar"><i style="width:${x[2]}"></i></div></div>`).join('')}</div><div class="panel"><h2 class="section-title">ประกาศที่เปิดใช้งานล่าสุด</h2><div class="admin-notice"><span>ด่วนที่สุด</span> ปิดปรับปรุงระบบห้อง IT อาคาร 3 วันพรุ่งนี้ที่ 15</div><div class="admin-notice"><span>ทั่วไป</span> เปิดให้จองห้องพักเรียนสอบกลางภาคแล้ว</div></div></div></div>`}
function adminTabPage(page){let data={
 'admin-rooms':['จัดการห้องประชุม','เพิ่ม แก้ไข และตรวจสอบสถานะห้องทั้งหมด', ['ห้องประชุม 1','ห้องประชุม 2','ห้องเรียน Smart Classroom 1','ห้องปฏิบัติการคอมพิวเตอร์ 204']],
 'admin-approvals':['อนุมัติการจอง','ตรวจสอบคำขอและอนุมัติการใช้งานห้อง', ['กิตติศักดิ์ สีดี','อาจารย์ พรชนก','สุดเขต สุขใจ']],
 'admin-usage':['ตารางการใช้งาน','ติดตามรายการใช้งานห้องประจำวัน', ['ห้องประชุม 1','ห้องประชุม 2','ห้องอบรม 3']],
 'admin-users':['จัดการผู้ใช้งาน','ดูข้อมูลและสิทธิ์การใช้งานของสมาชิก', ['นมิตา จอมบุญ','กิตติศักดิ์ สีดี','อาจารย์ พรชนก']],
 'admin-reports':['สถิติการใช้งาน','รายงานสรุปการจองและการใช้ห้อง', ['ห้องประชุม','ห้องปฏิบัติการ','ห้องเรียน']],
 'admin-notices':['จัดการประกาศ','สร้างและแก้ไขประกาศสำหรับผู้ใช้งาน', ['ปิดปรับปรุงระบบห้อง IT อาคาร 3','เปิดให้จองห้องพักเรียนสอบกลางภาคแล้ว']]
}[page]||['แดชบอร์ดผู้ดูแล','ภาพรวมระบบจัดการห้อง',''];let rows=Array.isArray(data[2])?data[2]:[];return head(data[0],data[1])+`<div class="d-flex justify-content-between align-items-center mb-3"><h2 class="section-title mb-0">ข้อมูล${data[0]}</h2><button class="btn-green" onclick="toast('เพิ่มข้อมูลใหม่')"><i class="bi bi-plus-lg"></i> เพิ่มข้อมูล</button></div><div class="panel"><div class="data-table"><table><thead><tr><th>รายการ</th><th>รายละเอียด</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td><strong>${x}</strong></td><td>${i%2?'ข้อมูลล่าสุดจากระบบ':'คณะเกษตรศาสตร์ มหาวิทยาลัยราชภัฏอุบลราชธานี'}</td><td><span class="status ${i===1?'pending':'approved'}">${i===1?'รอตรวจสอบ':'ใช้งานอยู่'}</span></td><td><button class="btn-outline" onclick="toast('เปิดรายละเอียดแล้ว')">รายละเอียด</button> <button class="btn-outline" onclick="toast('แก้ไขข้อมูลแล้ว')">แก้ไข</button></td></tr>`).join('')}</tbody></table></div></div>`}
function search(){let keyword=normalizeSearch(state.search);let list=rooms.filter(r=>(!keyword||normalizeSearch(`${r.name}${r.building}${r.type}`).includes(keyword))&&(!state.type||state.type==='ทั้งหมด'||r.type===state.type));return head('ค้นหาและจองห้องพัก','กรองรายละเอียดตามความต้องการ วันและเวลาที่สะดวก เพื่อจองพื้นที่สำหรับการเรียนและการประชุม')+`<div class="panel filter-panel"><h2 class="section-title">ตัวกรองละเอียด</h2><div class="row g-3"><div class="col-md-3"><label class="label">วันที่จอง</label><input class="form-control" type="date" value="2026-10-12"></div><div class="col-md-3"><label class="label">ช่วงเวลา</label><select class="form-select"><option>09:00 - 12:00 น.</option><option>13:00 - 16:00 น.</option></select></div><div class="col-md-3"><label class="label">ประเภทห้อง</label><select class="form-select" onchange="state.type=this.value;render()"><option>ทั้งหมด</option><option>ห้องประชุม</option><option>ห้องปฏิบัติการ</option><option>ห้องเรียน</option></select></div><div class="col-md-3"><label class="label">ความจุเข้าร่วม (คน)</label><select class="form-select"><option>15 - 30 คน</option><option>มากกว่า 30 คน</option></select></div></div><div class="mt-3"><label class="label text-success">อุปกรณ์ที่จำเป็น</label><div class="check-row"><label><input type="checkbox" checked> โปรเจคเตอร์</label><label><input type="checkbox" checked> คอมพิวเตอร์</label><label><input type="checkbox"> ไมโครโฟน</label><label><input type="checkbox"> กระดานอัจฉริยะ</label></div></div></div><div class="d-flex justify-content-between align-items-center mb-2"><h2 class="section-title">พบผลลัพธ์การค้นหา ${list.length} ห้อง</h2><span class="muted">อัปเดตล่าสุดวันนี้</span></div><div class="room-grid">${list.map(roomCard).join('')}</div>`}
function detail(){let r=room(state.selectedRoom);return head('รายละเอียดห้องประชุม',`${esc(r.name)} • ข้อมูลสิ่งอำนวยความสะดวก ตารางการเข้าใช้งาน และเงื่อนไขการใช้ห้อง`)+`<div class="detail-layout"><div><img class="hero-room" src="${safeImageUrl(r.img)}" alt="${esc(r.name)}"><div class="panel mt-3"><h2 class="section-title">ตารางการเข้าใช้สัปดาห์นี้</h2>${schedule(r)}</div></div><div><h2 class="detail-title">${esc(r.name)}</h2><div class="info-line">${esc(r.building)} • ห้องประชุม ชั้น ${Number(r.id)||0}</div><div class="room-stats"><span>ความจุ<strong>${Number(r.capacity)||0} คน</strong></span><span>เวลาให้บริการ<strong>08:30 - 17:30 น.</strong></span><span>ประเภท<strong>ผู้บริหาร / สัมมนา</strong></span></div><label class="label">สิ่งอำนวยความสะดวกในห้อง</label><div class="feature">${(r.features||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div><button class="btn-green w-100" onclick="go('booking')"><i class="bi bi-calendar-check"></i> จองห้องนี้</button><button class="btn-outline w-100 mt-2" onclick="go('rules')">อ่านกฎเกณฑ์</button></div></div>`}
function schedule(){let days=['จันทร์','อังคาร','พุธ','พฤหัสฯ','ศุกร์'];let times=['08:00 น.','10:00 น.','12:00 น.','14:00 น.','16:00 น.'];return `<div class="calendar compact"><div></div>${times.map(t=>`<div class="day">${t}</div>`).join('')}${days.map((d,i)=>`<div class="time fw-bold">${d}</div>${times.map((t,j)=>{let busy=(i+j)%4===0;return `<button class="slot ${busy?'busy':'available'}" ${busy?'disabled':`onclick="selectSlot('${d}','${t}')"`}>${busy?'จองเต็มแล้ว':'ว่าง'}</button>`}).join('')}`).join('')}</div>`}
function selectSlot(day,time){state.selectedSlot={day,time};go('booking');setTimeout(()=>{let select=document.querySelector('[name="time"]');if(select){let option=[...select.options].find(item=>item.value===time);if(!option){option=document.createElement('option');option.value=time;option.textContent=time;select.appendChild(option)}select.value=time}let summary=document.querySelector('.summary-date div:nth-child(2)');if(summary)summary.innerHTML=`<i class="bi bi-clock text-success"></i> เวลา: ${time}`},0)}
function booking(){let r=room(state.selectedRoom);return head('กรอกแบบฟอร์มการจองห้อง','โปรดตรวจสอบรายละเอียดข้อมูลการจองและวัตถุประสงค์ในการเข้าใช้งานให้ถูกต้องครบถ้วน')+`<div class="booking-grid"><div class="panel"><h2 class="section-title">ข้อมูลผู้จองและวัตถุประสงค์</h2><form id="bookingForm" onsubmit="submitBooking(event)"><div class="row g-3"><div class="col-md-6"><label class="label">ชื่อผู้จอง <b class="text-danger">*</b></label><input required name="name" class="form-control" value="นางสาวนิตา จอมบุญ"></div><div class="col-md-6"><label class="label">รหัสนักศึกษา / บุคลากร <b class="text-danger">*</b></label><input required name="code" class="form-control" value="67122040230"></div><div class="col-12"><label class="label">คณะ / สาขาวิชา / หน่วยงาน <b class="text-danger">*</b></label><input required name="department" class="form-control" value="คณะเทคโนโลยีอุตสาหกรรม สาขาเทคโนโลยีมัลติมีเดียและแอนิเมชัน"></div><div class="col-md-6"><label class="label">วัตถุประสงค์ในการเข้าใช้ <b class="text-danger">*</b></label><input required name="purpose" class="form-control" placeholder="ระบุวัตถุประสงค์ เช่น ประชุมสัมมนา"></div><div class="col-md-6"><label class="label">จำนวนผู้เข้าร่วม (คน) <b class="text-danger">*</b></label><input required name="people" type="number" min="1" max="${r.capacity}" class="form-control" placeholder="เช่น 10 คน"></div><div class="col-12"><label class="label">อุปกรณ์เพิ่มเติมที่ต้องการจอง</label><div class="check-row"><label><input type="checkbox" name="equipment" value="สาย HDMI"> สายต่อ HDMI</label><label><input type="checkbox" name="equipment" value="ไมโครโฟนไร้สาย"> ไมโครโฟนไร้สาย</label><label><input type="checkbox" name="equipment" value="โต๊ะนำเสนอ"> โต๊ะนำเสนอ</label></div></div><div class="col-md-6"><label class="label">วันที่ใช้งาน</label><input required name="date" type="date" class="form-control" value="2026-10-12"></div><div class="col-md-6"><label class="label">เวลาที่ใช้งาน</label><select name="time" class="form-select"><option>09:00 - 12:00 น.</option><option>13:00 - 16:00 น.</option><option>09:00 - 16:00 น.</option></select></div><div class="col-12"><label class="label">หมายเหตุ / ความต้องการพิเศษอื่นๆ</label><textarea name="note" class="form-control" rows="3" placeholder="กรอกรายละเอียดเพิ่มเติมถ้ามี..."></textarea></div></div><label class="rule-check"><input required type="checkbox"> ข้าพเจ้ายอมรับและปฏิบัติตามกฎการใช้ห้องของมหาวิทยาลัยราชภัฏอุบลราชธานี</label><button class="btn-green w-100">ยืนยันการจอง</button></form></div><div class="panel booking-summary"><h2 class="section-title">รายละเอียดการจอง</h2><div class="summary-room"><img src="${r.img}" alt=""><div><strong>${r.name}</strong><div class="muted">${r.building}</div></div></div><div class="summary-date"><div><i class="bi bi-calendar3 text-success"></i> วันที่: วันจันทร์ 12 ตุลาคม 2569</div><div><i class="bi bi-clock text-success"></i> เวลา: 09:00 - 12:00 น.</div></div><button class="btn-outline w-100" onclick="go('detail')">ยกเลิก</button></div></div>`}
function submitBooking(e){e.preventDefault();let f=new FormData(e.target);bookings.push({id:Date.now(),roomId:state.selectedRoom,name:f.get('name'),code:f.get('code'),purpose:f.get('purpose'),people:f.get('people'),date:f.get('date'),time:f.get('time'),status:'รออนุมัติ',createdAt:new Date().toISOString()});save();toast('บันทึกการจองเรียบร้อยแล้ว');setTimeout(()=>go('bookings'),500)}
function bookingsPage(){return head('การจองของฉัน','ตรวจสอบสถานะการจองห้องเรียน ห้องประชุม และรายการที่คุณกำลังเข้าใช้บริการ')+`<div class="d-flex gap-2 mb-3"><button class="btn-green">ทั้งหมด <span class="badge bg-light text-success">${bookings.length}</span></button><button class="btn-outline">รออนุมัติ <span class="badge bg-light text-secondary">${bookings.filter(b=>b.status==='รออนุมัติ').length}</span></button><button class="btn-outline">อนุมัติแล้ว</button><button class="btn-outline">ยกเลิก</button></div><div class="data-table"><table><thead><tr><th>ห้องที่จอง</th><th>วันที่ใช้งาน</th><th>เวลาที่ใช้</th><th>สถานะการจอง</th><th>จัดการการจอง</th></tr></thead><tbody>${bookings.length?bookings.map(b=>{let r=room(b.roomId);return `<tr><td><strong>${r.name}</strong><br><span class="muted">${r.building}</span></td><td>${formatDate(b.date)}</td><td>${b.time}</td><td><span class="status ${b.status==='ยกเลิก'?'cancelled':b.status==='อนุมัติแล้ว'?'approved':'pending'}">${b.status}</span></td><td><div class="actions"><button class="btn-outline" onclick="state.selectedRoom=${r.id};go('detail')">รายละเอียด</button>${b.status!=='ยกเลิก'?`<button class="btn-danger" onclick="cancelBooking(${b.id})">ยกเลิกการจอง</button>`:''}</div></td></tr>`}).join(''):`<tr><td colspan="5" class="text-center py-5 text-muted">ยังไม่มีรายการจอง ลองค้นหาและจองห้องได้เลย</td></tr>`}</tbody></table></div>`}
function cancelBooking(id){let b=bookings.find(x=>x.id===id);if(b){b.status='ยกเลิก';save();render();toast('ยกเลิกการจองแล้ว')}}
function calendarPage(){return head('ปฏิทินแสดงตารางจอง','ดูการใช้งานประจำสัปดาห์ปัจจุบัน แยกประเภทตามห้อง')+`<div class="d-flex justify-content-between mb-3"><div class="btn-group"><button class="btn-outline">รายวัน</button><button class="btn-green">รายสัปดาห์</button><button class="btn-outline">รายเดือน</button></div><select class="form-select" style="width:150px"><option>ห้องประชุม 1</option>${rooms.slice(1).map(r=>`<option>${r.name}</option>`).join('')}</select></div><div class="panel calendar-wrap"><div class="calendar"><div></div>${['จันทร์ 6','อังคาร 7','พุธ 8','พฤหัสฯ 9','ศุกร์ 10'].map(d=>`<div class="day">${d}</div>`).join('')}${['08:00 น.','09:00 น.','10:00 น.','11:00 น.','12:00 น.','13:00 น.','14:00 น.','15:00 น.','16:00 น.'].map((t,i)=>`<div class="time">${t}</div>${[0,1,2,3,4].map((_,j)=>`<div class="slot ${((i+j)%5===0)?'busy':((i+j)%7===0)?'mine':''}">${((i+j)%5===0)?'จองโดย วท.บ.':((i+j)%7===0)?'ว่างสำหรับจอง':'ว่างสำหรับจอง'}</div>`).join('')}`).join('')}</div></div>`}
function historyPage(){return head('ประวัติการใช้บริการห้อง','ดูข้อมูลและสถิติการเข้าใช้งานและการจัดกิจกรรมของคุณในมหาวิทยาลัย')+`<div class="history-stats"><div class="stat-card"><div class="stat-icon"><i class="bi bi-book"></i></div><div><span class="muted">การจองห้องทั้งหมด</span><strong>${bookings.length+18} ครั้ง</strong></div></div><div class="stat-card"><div class="stat-icon" style="background:#e8fbf4;color:#20b98a"><i class="bi bi-clock"></i></div><div><span class="muted">ชั่วโมงเรียน/จองสะสม</span><strong>45 ชั่วโมง</strong></div></div><div class="stat-card"><div class="stat-icon" style="background:#fff5df;color:#f2a20b"><i class="bi bi-house"></i></div><div><span class="muted">ห้องที่ใช้งานบ่อยสุด</span><strong>ห้องประชุม 1</strong></div></div></div><div class="panel"><div class="d-flex justify-content-between mb-3"><span class="muted">ตัวเลือกวันที่ย้อนหลัง: <b class="bg-light p-2 rounded">1 ก.ค. 2566 - 31 ต.ค. 2566</b></span><button class="btn-outline text-success">ส่งออกไฟล์รายงาน (CSV)</button></div><div class="data-table"><table><thead><tr><th>ห้องที่ใช้</th><th>วันที่ใช้งาน</th><th>เวลาที่ใช้</th><th>วัตถุประสงค์หลัก</th><th>สถานะประวัติ</th></tr></thead><tbody>${(bookings.length?bookings:rooms.slice(0,4).map((r,i)=>({roomId:r.id,date:`2026-09-${28+i}`,time:i%2?'13:00 - 17:00 น.':'09:00 - 12:00 น.',purpose:'การประชุมและการเรียน',status:'เสร็จสิ้น'}))).map(b=>{let r=room(b.roomId);return `<tr><td><strong>${r.name}</strong><br><span class="muted">${r.building}</span></td><td>${formatDate(b.date)}</td><td>${b.time}</td><td>${b.purpose||'การประชุมและการเรียน'}</td><td><span class="status done">${b.status==='ยกเลิก'?'ยกเลิกแล้ว':'เสร็จสิ้น'}</span></td></tr>`}).join('')}</tbody></table></div></div>`}
function notificationsPage(){return head('แจ้งเตือน','ติดตามข่าวสาร สถานะการจอง และประกาศสำคัญจากระบบจองห้อง')+`<div class="notification-toolbar"><button class="btn-green" onclick="markNotificationsRead()"><i class="bi bi-check2-all"></i> อ่านทั้งหมด</button><button class="btn-outline" onclick="clearNotifications()"><i class="bi bi-trash3"></i> ล้างการแจ้งเตือน</button></div><div id="notificationList"><div class="notification-item unread"><div class="notification-icon success"><i class="bi bi-check-circle"></i></div><div class="notification-content"><strong>การจองห้องได้รับการอนุมัติ</strong><p>ห้องประชุม 2 วันที่ 8 ตุลาคม 2569 เวลา 13:00 - 16:00 น. ได้รับการอนุมัติแล้ว</p><small>วันนี้ เวลา 09:30 น.</small></div><span class="notification-dot"></span></div><div class="notification-item unread"><div class="notification-icon warning"><i class="bi bi-clock-history"></i></div><div class="notification-content"><strong>มีรายการจองรอการอนุมัติ</strong><p>ห้องประชุม 1 วันที่ 12 ตุลาคม 2569 กำลังรอผู้ดูแลตรวจสอบ</p><small>เมื่อวาน เวลา 16:20 น.</small></div><span class="notification-dot"></span></div><div class="notification-item"><div class="notification-icon info"><i class="bi bi-megaphone"></i></div><div class="notification-content"><strong>ประกาศจากผู้ดูแลระบบ</strong><p>โปรดตรวจสอบกฎและเงื่อนไขการใช้บริการห้องก่อนทำการจองทุกครั้ง</p><small>3 วันที่แล้ว</small></div></div><div class="notification-item"><div class="notification-icon muted-icon"><i class="bi bi-calendar-event"></i></div><div class="notification-content"><strong>แจ้งเตือนก่อนถึงเวลาจอง</strong><p>คุณมีรายการจองห้องประชุม 3 ในวันพรุ่งนี้ เวลา 09:00 น.</p><small>5 วันที่แล้ว</small></div></div></div>`}
function adminNotificationsPage(){return head('แจ้งเตือนผู้ดูแลระบบ','รายการแจ้งเตือนที่ต้องตรวจสอบและดำเนินการ')+`<div class="notification-toolbar"><button class="btn-green" onclick="markNotificationsRead()"><i class="bi bi-check2-all"></i> อ่านทั้งหมด</button><button class="btn-outline" onclick="clearNotifications()"><i class="bi bi-trash3"></i> ล้างการแจ้งเตือน</button></div><div id="notificationList"><div class="notification-item unread"><div class="notification-icon warning"><i class="bi bi-hourglass-split"></i></div><div class="notification-content"><strong>มีคำขอจองใหม่รออนุมัติ 5 รายการ</strong><p>ผู้ใช้งานส่งคำขอจองห้องประชุมและห้องปฏิบัติการ โปรดตรวจสอบรายละเอียด</p><small>วันนี้ เวลา 09:30 น.</small></div><span class="notification-dot"></span></div><div class="notification-item unread"><div class="notification-icon danger-icon"><i class="bi bi-calendar-x"></i></div><div class="notification-content"><strong>มีผู้ใช้ยกเลิกการจอง</strong><p>ห้องประชุม 1 วันที่ 12 ต.ค. 2569 เวลา 10:00 น. ถูกยกเลิก ทำให้ช่วงเวลากลับมาว่าง</p><small>วันนี้ เวลา 08:45 น.</small></div><span class="notification-dot"></span></div><div class="notification-item unread"><div class="notification-icon info"><i class="bi bi-tools"></i></div><div class="notification-content"><strong>มีการแจ้งปัญหาอุปกรณ์ห้อง</strong><p>ห้องปฏิบัติการ 204 แจ้งว่าโปรเจคเตอร์ไม่สามารถใช้งานได้</p><small>เมื่อวาน เวลา 16:20 น.</small></div><span class="notification-dot"></span></div><div class="notification-item"><div class="notification-icon success"><i class="bi bi-megaphone"></i></div><div class="notification-content"><strong>ประกาศถูกเผยแพร่แล้ว</strong><p>ประกาศ “เปิดให้จองห้องพักเรียนสอบกลางภาคแล้ว” แสดงแก่ผู้ใช้งานเรียบร้อย</p><small>3 วันที่แล้ว</small></div></div></div>`}
function markNotificationsRead(){document.querySelectorAll('.notification-item').forEach(item=>item.classList.remove('unread'));toast('อ่านการแจ้งเตือนทั้งหมดแล้ว')}
function clearNotifications(){let list=document.getElementById('notificationList');if(list){list.innerHTML='<div class="empty-notification"><i class="bi bi-bell-slash"></i><p>ไม่มีการแจ้งเตือน</p></div>';toast('ล้างการแจ้งเตือนแล้ว')}}
function applyTheme(){document.body.classList.toggle('dark-mode',false)}
function toggleTheme(){document.body.classList.toggle('dark-mode');render()}
function rules(){let rules=[['clock','1. เวลาปิด-เปิดให้บริการ','ระบบมีการให้บริการห้องเรียนและห้องประชุมตั้งแต่เวลา 08:30 - 18:00 น. ในวันธรรมดาและวันที่ทำการปกติ กรณีที่ต้องการใช้งานนอกเหนือเวลาดังกล่าวต้องทำเรื่องขออนุมัติเป็นกรณีพิเศษจากคณะประจำอาคาร'],['door-open','2. สิ่งที่ห้ามกระทำโดยเด็ดขาด','ห้ามนำปลั๊กไฟ อาหาร หรือเครื่องดื่มประเภทแอลกอฮอล์ และอุปกรณ์ผิดกฎหมายเข้ามาภายในห้องโดยเด็ดขาด ห้ามกระทำการรบกวนหรือจัดส่งเสียงดังรบกวนนักศึกษาหรือบุคลากรอื่น'],['shield','3. ความรับผิดชอบต่ออุปกรณ์ห้องพัก','ผู้จองมีหน้าที่ตรวจสอบสภาพอุปกรณ์ก่อนการใช้งาน อาทิ ปลั๊กไฟ คอมพิวเตอร์ สายเชื่อมต่อ และอุปกรณ์ที่ให้พร้อมใช้งาน หากพบข้อผิดพลาดต้องแจ้งเจ้าหน้าที่ทันที'],['check-lg','4. วิธีปฏิบัติในการคืนห้อง','ก่อนสิ้นสุดเวลาการจอง 10 นาที โปรดทำความสะอาดและเก็บของให้เรียบร้อย ปิดเครื่องปรับอากาศและอุปกรณ์แล้วล็อกประตูห้องให้เรียบร้อย'],['card-text','5. เงื่อนไขและกฎเกณฑ์การยกเลิกการจอง','ผู้ใช้งานสามารถยกเลิกการจองผ่านปุ่มยกเลิกการจองได้ โดยควรยกเลิกล่วงหน้าอย่างน้อย 24 ชั่วโมง เพื่อให้ผู้ใช้งานท่านอื่นสามารถจองพื้นที่ได้อย่างเหมาะสม']];return head('กฎและเงื่อนไขการใช้บริการห้อง','ข้อตกลง ความรับผิดชอบ และระเบียบปฏิบัติร่วมกันของนักศึกษาและบุคลากรมหาวิทยาลัย')+`<div class="rule-alert"><strong><i class="bi bi-shield-exclamation"></i> คำเตือนเรื่องมารยาทและระเบียบวินัยส่วนรวม</strong><br><span class="small">หากตรวจสอบพบการกระทำความผิดซ้ำซ้อน อาจเป็นเหตุให้ระงับสิทธิ์การใช้งานโดยไม่แจ้งล่วงหน้า</span></div>${rules.map(x=>`<div class="rule-item"><div class="rule-icon"><i class="bi bi-${x[0]}"></i></div><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('')}`}
function developerPage(){let members=[['นาย นัฐภูมิ มะเฮง','67122040205','assets/member-natthaphum.webp','center 25%'],['นาย พงศกร เพ็งกลาง','67122040213','assets/member-pongsakorn.webp','center 32%'],['นายรชต อนุมาตย์','67122040220','assets/member-rachata.webp','center 22%'],['นางสาวธารารัตน์ เรืองแสน','67122040224','assets/member-thararat.webp','center 38%'],['นางสาวปณิตา อบมาสุ่ย','67122040230','assets/member-panita.webp','center 42%']];return head('ผู้พัฒนาเว็บไซต์','ข้อมูลเกี่ยวกับทีมพัฒนาระบบจองห้อง คณะเกษตรศาสตร์ มหาวิทยาลัยราชภัฏอุบลราชธานี')+`<section class="developer-page" aria-label="ข้อมูลผู้พัฒนาเว็บไซต์"><section class="developer-section"><div class="developer-advisor panel"><div class="developer-advisor-avatar"><img class="developer-advisor-photo" src="assets/advisor.webp" alt="รองศาสตราจารย์ ดร.ชัดชัย แก้วตา"></div><div class="developer-advisor-info"><h3>รองศาสตราจารย์ ดร.ชัดชัย แก้วตา</h3></div></div></section><section class="developer-section developer-team-section"><div class="developer-section-heading"><div><h2 class="section-title">ทีมพัฒนาระบบ</h2><p class="muted">สมาชิกผู้พัฒนาระบบจองห้อง</p></div></div><div class="developer-team-grid">${members.map(([name,id,image,position])=>`<article class="developer-member-card panel"><div class="developer-member-avatar"><img class="developer-member-photo" src="${image}" alt="${name}" style="object-position:${position}"></div><div class="developer-member-info"><h3>${name}</h3><div class="developer-student-label">รหัสนักศึกษา</div><strong class="developer-student-id">${id}</strong><div class="developer-member-role">สมาชิกทีมพัฒนา</div></div></article>`).join('')}</div></section></section>`}
function formatDate(d){if(!d)return '-';let [y,m,day]=d.split('-');return `${day} ${['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][Number(m)-1]} ${Number(y)+543}`}
function login(){return `<div class="login-page"><div class="login-card"><div class="login-mark"><i class="bi bi-buildings"></i></div><h1>ระบบจองห้อง คณะเกษตรศาสตร์<br>มหาวิทยาลัยราชภัฏอุบลราชธานี</h1><p>กรุณาเข้าสู่ระบบด้วยบัญชีมหาวิทยาลัยของคุณ</p><form onsubmit="doLogin(event)" class="text-start"><label class="label">อีเมลนักศึกษา / บุคลากร</label><input id="loginEmail" class="form-control" type="email" placeholder="example@ubru.ac.th" required><label class="label mt-3">รหัสผ่าน</label><input id="loginPassword" class="form-control" type="password" placeholder="••••••••••••" required><div class="forgot-password text-end"><span class="text-muted">ลืมรหัสผ่าน?</span></div><button class="btn-green">เข้าสู่ระบบ</button></form><div class="login-help">บัญชี Admin สำหรับทดสอบ: <b>admin@ubru.test</b><br>ระบบนี้ใช้สำหรับ TEST / EDUCATION ONLY<br>มีปัญหาการเข้าใช้งาน? กรุณาติดต่อผู้ดูแลระบบ</div></div></div>`}
function doLogin(event){event.preventDefault();let email=document.getElementById('loginEmail').value.trim().toLowerCase();let adminEmail=email==='admin@ubru.ac.th'||email.startsWith('admin@')||email.includes('.admin@');loginAs(adminEmail?'admin':'user')}
function loginAs(){toast('กรุณาเข้าสู่ระบบด้วยอีเมลและรหัสผ่าน')}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function logout(){apiRequest('/api/auth/logout',{method:'POST'}).catch(()=>{}).finally(()=>{setCurrentUser(null);state.page='login';location.hash='login';render();toast('ออกจากระบบเรียบร้อยแล้ว')})}
function adminTablePage(title,desc,headers,rows,button='เพิ่มข้อมูล'){return head(title,desc)+`<div class="d-flex justify-content-between align-items-center mb-3"><h2 class="section-title mb-0">ข้อมูล${title}</h2><button class="btn-green" onclick="toast('${button}ใหม่')"><i class="bi bi-plus-lg"></i> ${button}</button></div><div class="panel"><div class="data-table"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
